import fs from 'fs';
import path from 'path';
import { ProjectStorage } from './ProjectStorage';
import { createLogger } from '../utils/logger';
import type {
  VariantHistoryManifest,
  VariantHistoryStatus,
  VariantIndexEntry,
  VariantIndexEntryInput,
} from '../types/variant-history';
export type {
  VariantIndexEntry,
  VariantIndexEntryInput,
} from '../types/variant-history';
import { ProjectMetadataRecords } from '../storage/project-metadata/ProjectMetadataRecords';
import {
  PROJECT_METADATA_MIGRATIONS,
  UnsupportedSchemaVersionError,
  type ProjectMetadataMigration,
} from '../storage/project-metadata/migrations';

const log = createLogger('ProjectMetadataStore');

const DATABASE_FILENAME = 'rivet.db';

const DATABASE_SIBLING_SUFFIXES = ['-wal', '-shm'] as const;

const VARIANT_INDEX_STATE_KEY = 'variant_index_state';
const VARIANT_INDEX_READY = 'ready';
const VARIANT_INDEX_STALE = 'stale';

const VARIANTS_UI_STATE_KEY = 'variants_ui_state';

export class ProjectMetadataStore {
  private readonly handles = new Map<string, ProjectMetadataRecords>();
  private readonly staleOverrides = new Set<string>();
  private readonly migrations: readonly ProjectMetadataMigration[];

  constructor(
    migrations: readonly ProjectMetadataMigration[] = PROJECT_METADATA_MIGRATIONS,
    private readonly storage: ProjectStorage = new ProjectStorage(),
  ) {
    this.migrations = migrations;
  }

  databasePath(projectPath: string): string {
    return path.join(
      this.storage.resolve(projectPath).dataDirectory,
      DATABASE_FILENAME,
    );
  }

  hasDatabase(projectPath: string): boolean {
    return fs.existsSync(this.databasePath(projectPath));
  }

  async initialize(projectPath: string): Promise<void> {
    await this.openDatabase(projectPath);
  }

  async upsertVariantFromManifest(args: {
    projectPath: string;
    manifest: VariantHistoryManifest;
    manifestMtimeMs: number;
    hasStaticPreview: boolean;
  }): Promise<void> {
    const db = await this.openDatabase(args.projectPath);
    db.upsert(args);
  }

  async rebuildVariantIndex(args: {
    projectPath: string;
    entries: VariantIndexEntryInput[];
  }): Promise<void> {
    const db = await this.openDatabase(args.projectPath);
    db.transaction(() => {
      db.clearVariants();
      for (const entry of args.entries) db.upsert(entry);
      db.writeState(VARIANT_INDEX_STATE_KEY, VARIANT_INDEX_READY);
    });
    this.staleOverrides.delete(path.resolve(args.projectPath));
  }

  async isVariantIndexReady(projectPath: string): Promise<boolean> {
    if (this.staleOverrides.has(path.resolve(projectPath))) return false;
    if (!this.handles.has(path.resolve(projectPath))) {
      if (!this.hasDatabase(projectPath)) return false;
    }
    const db = await this.openDatabase(projectPath);
    return db.readState(VARIANT_INDEX_STATE_KEY) === VARIANT_INDEX_READY;
  }

  async markVariantIndexStale(projectPath: string): Promise<void> {
    this.staleOverrides.add(path.resolve(projectPath));
    try {
      const db = await this.openDatabase(projectPath);
      db.writeState(VARIANT_INDEX_STATE_KEY, VARIANT_INDEX_STALE);
    } catch (err) {
      log.warn(
        `markVariantIndexStale: durable stale flag failed for ${projectPath} — the in-memory override still forces a rebuild in this process`,
        err,
      );
    }
  }

  async listVariants(args: {
    projectPath: string;
    limit?: number;
    status?: VariantHistoryStatus;
  }): Promise<VariantIndexEntry[]> {
    const db = await this.openDatabase(args.projectPath);
    return db.list({ status: args.status, limit: args.limit });
  }

  async searchVariants(args: {
    projectPath: string;
    query: string;
    limit?: number;
  }): Promise<VariantIndexEntry[]> {
    const db = await this.openDatabase(args.projectPath);
    return db.search({ query: args.query, limit: args.limit });
  }

  async readVariantsUiState(projectPath: string): Promise<string | null> {
    if (!this.hasDatabase(projectPath)) return null;
    const db = await this.openDatabase(projectPath);
    return db.readState(VARIANTS_UI_STATE_KEY);
  }

  async writeVariantsUiState(projectPath: string, json: string): Promise<void> {
    const db = await this.openDatabase(projectPath);
    db.writeState(VARIANTS_UI_STATE_KEY, json);
  }

  closeAll(): void {
    for (const [key, db] of this.handles) {
      try {
        db.close();
      } catch (err) {
        log.warn(`closeAll: failed to close database for ${key}`, err);
      }
    }
    this.handles.clear();
  }

  private async openDatabase(
    projectPath: string,
  ): Promise<ProjectMetadataRecords> {
    const key = path.resolve(projectPath);
    const dbPath = this.databasePath(key);
    const existing = this.handles.get(key);
    if (existing) {
      if (fs.existsSync(dbPath)) return existing;
      try {
        existing.close();
      } catch (err) {
        log.warn(`openDatabase: failed to close stale handle for ${key}`, err);
      }
      this.handles.delete(key);
    }

    fs.mkdirSync(path.dirname(dbPath), { recursive: true });

    let db: ProjectMetadataRecords;
    try {
      db = await ProjectMetadataRecords.open(dbPath, this.migrations);
    } catch (err) {
      if (err instanceof UnsupportedSchemaVersionError) throw err;
      log.warn(
        `openDatabase: ${dbPath} is unreadable — recreating the projection`,
        err,
      );
      this.deleteDatabaseFiles(dbPath);
      db = await ProjectMetadataRecords.open(dbPath, this.migrations);
    }
    if (db.wasUpgraded) {
      this.staleOverrides.add(key);
      try {
        db.writeState(VARIANT_INDEX_STATE_KEY, VARIANT_INDEX_STALE);
      } catch (err) {
        log.warn(
          `openDatabase: durable stale flag failed after upgrading ${dbPath}`,
          err,
        );
      }
    }
    this.handles.set(key, db);
    return db;
  }

  private deleteDatabaseFiles(dbPath: string): void {
    for (const target of [
      dbPath,
      ...DATABASE_SIBLING_SUFFIXES.map((suffix) => `${dbPath}${suffix}`),
    ]) {
      try {
        fs.rmSync(target, { force: true });
      } catch (err) {
        log.warn(`deleteDatabaseFiles: failed to remove ${target}`, err);
      }
    }
  }
}
